inline void fillOriginalFade(float* output, int length) {
    if (length<8 || length>4096 || (length&(length-1)))
        throw std::invalid_argument("Original fade supports power-of-two length=8..4096");
    static_assert(sizeof(float)==sizeof(std::uint32_t), "IEEE754 binary32 required");
    const auto* table=original_fade_data::bits+length-8;
    for (int i=0; i<length; ++i)
        std::memcpy(output+i,table+i,sizeof(float));
}
